fn npc_12075(ctx: &Context, mut pc: usize, args: Vec<Value>) -> Result<Value, String> {
    const LABEL_ONINSTANCEINIT: usize = 1;
    const LABEL_ONENABLE: usize = 2;
    const LABEL_ONTIMER500: usize = 3;
    const LABEL_ONTIMER5500: usize = 4;
    const LABEL_ONTIMER10500: usize = 5;
    'sm: loop {
        match pc {
                0 => {
                    if op(ctx.call(Function::CheckWeight, vec![n(1201), n(1)])?, "==", n(0))?.truthy() {
                        ctx.mes("You're carrying too much stuff. Why don't you put some of it away, and then come back?")?;
                        ctx.close()?;
                        return Err(END.into());
                    }
                    ctx.mes("[Lost Souls]")?;
                    ctx.mes("It's you that have liberated us from the evil Naght Sieger.")?;
                    ctx.next()?;
                    ctx.mes("[Lost Souls]")?;
                    ctx.mes("Thank you so much. Now we can escape from this cold and dark place... to heaven.")?;
                    ctx.next()?;
                    if (op(ctx.call(Function::CountItem, vec![n(13412)])?, ">", n(0))?.truthy() && op(ctx.call(Function::CountItem, vec![n(13413)])?, ">", n(0))?.truthy()) {
                        ctx.mes("[Lost Souls]")?;
                        ctx.mes("Hey, you have the remnants of Naght Sieger with you.")?;
                        ctx.next()?;
                        ctx.mes("[Lost Souls]")?;
                        ctx.mes("They may appear to be one-handed swords, but I can put them together to make a two-handed one if you want. That's the only way I can repay you for freeing me.")?;
                        ctx.next()?;
                        'b1: {
                            let sw1 = n(select(ctx, &["Make a Two-Handed Sword.", "No, thanks."])?);
                            let mut m1 = false;
                            let d1 = !eq(&sw1, &n(1)) && !eq(&sw1, &n(2));
                            if !m1 && eq(&sw1, &n(1)) { m1 = true; }
                            if m1 {
                                ctx.mes("[Lost Souls]")?;
                                ctx.mes("If it is already upgraded or has a card inside, those effects will be disappear. Is this ok with you?")?;
                                ctx.next()?;
                                'b2: {
                                    let sw2 = n(select(ctx, &["It's fine with me. Please make one.", "No way!"])?);
                                    let mut m2 = false;
                                    let d2 = !eq(&sw2, &n(1)) && !eq(&sw2, &n(2));
                                    if !m2 && eq(&sw2, &n(1)) { m2 = true; }
                                    if m2 {
                                        ctx.mes("[Lost Souls]")?;
                                        ctx.mes("Good, then I'll combine these to create a two-handed sword.")?;
                                        ctx.next()?;
                                        ctx.call(Function::DelItem, vec![n(13412), n(1)])?;
                                        ctx.call(Function::DelItem, vec![n(13413), n(1)])?;
                                        ctx.call(Function::GetItem, vec![n(1185), n(1)])?;
                                        break 'b2;
                                    }
                                    if !m2 && eq(&sw2, &n(2)) { m2 = true; }
                                    if m2 {
                                        ctx.mes("[Lost Souls]")?;
                                        ctx.mes("I see. I guess you aren't as greedy or ambitious as those other adventurers.")?;
                                        ctx.next()?;
                                        break 'b2;
                                    }
                                }
                                break 'b1;
                            }
                            if !m1 && eq(&sw1, &n(2)) { m1 = true; }
                            if m1 {
                                ctx.mes("[Lost Souls]")?;
                                ctx.mes("I see. I guess you aren't as greedy or ambitious as those other adventurers.")?;
                                ctx.next()?;
                                break 'b1;
                            }
                        }
                    }
                    ctx.mes("[Lost Souls]")?;
                    ctx.mes("I'd like to talk to you more, but I've... I've got to go now.")?;
                    ctx.next()?;
                    ctx.mes("[Lost Souls]")?;
                    ctx.mes("Farewell, young adventurer. I wish you good luck.")?;
                    ctx.close()?;
                    ctx.call(Function::Warp, vec![s("alberta"), n(223), n(36)])?;
                    return Err(END.into());
                    pc = 1;
                }
                1 => {
                    ctx.call(Function::DisableNpc, vec![ctx.call(Function::InstanceNpcName, vec![s("Lost Soul#102")])?])?;
                    return Err(END.into());
                    pc = 2;
                }
                2 => {
                    ctx.call(Function::InitNpcTimer, vec![])?;
                    ctx.call(Function::EnableNpc, vec![ctx.call(Function::InstanceNpcName, vec![s("Lost Soul#102")])?])?;
                    ctx.call(Function::DoNpcEvent, vec![op(ctx.call(Function::InstanceNpcName, vec![s("#Effect30")])?, "+", s("::OnEnable"))?])?;
                    return Err(END.into());
                    pc = 3;
                }
                3 => {
                    ctx.call(Function::MapAnnounce, vec![ctx.call(Function::InstanceMapName, vec![s("6@tower")])?, s("This... This can't be happening! I can't be defeated!"), constant(ctx, "BC_MAP")?, s("0xffff00")])?;
                    return Err(END.into());
                    pc = 4;
                }
                4 => {
                    ctx.call(Function::MapAnnounce, vec![ctx.call(Function::InstanceMapName, vec![s("6@tower")])?, s("Nooo! My soul... My shell...! Nooo~!"), constant(ctx, "BC_MAP")?, s("0xffff00")])?;
                    return Err(END.into());
                    pc = 5;
                }
                5 => {
                    ctx.call(Function::MapAnnounce, vec![ctx.call(Function::InstanceMapName, vec![s("6@tower")])?, s("Naght Sieger's body has turned into dark ashes that scattered in the wind."), constant(ctx, "BC_MAP")?, s("0x00ffcc")])?;
                    ctx.call(Function::StopNpcTimer, vec![])?;
                    return Err(END.into());
                    pc = 6;
                }
            6 => return Ok(n(0)),
            _ => return Err("Invalid script position".into()),
        }
    }
}

